const [label,image,expectedImageHash]=process.argv.slice(2);if(!['series52-49-before','series52-52-first','series52-52-second','series52-49-after'].includes(label)||!/^stage-one(?:49|52)\.js$/.test(image)||! /^[a-f0-9]{64}$/.test(expectedImageHash))throw Error('Invalid series recipe');if(process.version!=='v23.11.0')throw Error('Wrong runtime');
const runner=resolve('benchmark-linux.ts'),component=resolve(image),driver=resolve('evals/checker_core_step_runtime.mjs');if(hash(runner)!=='107be3470c240af8c069fdc39ccfebd080b473fb727a5943c9979d7370c987eb'||hash(driver)!=='2cad05bb4885854d7ede65336dbe287ac78063f8321110d2d63018e9890000fd'||hash(component)!==expectedImageHash)throw Error('Pinned identity drift');
if(label.includes('-49-')&&(image!=='stage-one49.js'||expectedImageHash!=='28061d5eab72b2a0bc560c6963b8f22cd863d7572f102cb627d483606f412e81'))throw Error('Wrong genuine49 control');if(label.includes('-52-')&&image!=='stage-one52.js')throw Error('Wrong genuine52 path');delete process.env.BEND_CHECKER_COUNTS_FILE;
const group=fs.readFileSync('/proc/self/cgroup','utf8').trim().split('\n').find(x=>x.startsWith('0::')).slice(3),cg='/sys/fs/cgroup'+group,safe=p=>{try{return fs.readFileSync(p,'utf8').trim();}catch(e){return {unavailable:String(e)};}};
const environment=()=>({at:new Date().toISOString(),loadavg:safe('/proc/loadavg'),allowedCpuAffinity:fs.readFileSync('/proc/self/status','utf8').split('\n').filter(x=>/^Cpus_allowed(?:_list)?:/.test(x)),cgroup:group,memoryMax:safe(cg+'/memory.max'),memorySwapMax:safe(cg+'/memory.swap.max'),cpuStat:safe(cg+'/cpu.stat'),cpuMax:safe(cg+'/cpu.max'),procCpuInfo:fs.readFileSync('/proc/cpuinfo','utf8').split('\n').filter(x=>/^(processor|model name|cpu MHz)\s*:/.test(x)),frequencyScope:'Reported proc/cpuinfo snapshots only, not hardware counters or sustained frequency; no affinity/governor/frequency settings changed.',nodeOptions:process.env.NODE_OPTIONS??null});
const o={mode:'component',corpus:resolve('corpus.relocated.json'),report:resolve(label+'.json'),driver,stopAfter:'compile',component,exports:resolve('official.json.exports.json')};if(fs.existsSync(o.report))throw Error('Fresh series report required');
const corpus=JSON.parse(fs.readFileSync(o.corpus)),names=JSON.parse(fs.readFileSync(o.exports)).exports;if(corpus.files.length!==50||names.length!==7720)throw Error('Coverage mismatch');
