const worker=new Worker(pathToFileURL(runner),{workerData:{requestPath:request,requestSha256:hash(request)},resourceLimits:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}});try{await new Promise((yes,no)=>{worker.once('error',no);worker.once('exit',code=>code===0?yes():no(Error('Worker exit '+code)));});}finally{save(label+'.environment-after.json',environment());}
const r=JSON.parse(fs.readFileSync(o.report));if(r.status!=='PASS'||r.inputFiles!==50||r.moduleCount!==15||r.checkedModules!==15||r.exportCount!==7720||!r.outputSmokePassed)throw Error('Incomplete full workload');
