import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,statSync,readdirSync} from 'node:fs';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
const root='/Users/ilyagulya/Projects/My/bend';
const dir=dirname(fileURLToPath(import.meta.url));
const hash=(x:string|Uint8Array)=>createHash('sha256').update(x).digest('hex');
const pin='6c1df3eb304fe085070aa4797928f70243b80d4635389e3d5d8a49fdfbb3051e';
const report:any={kind:'direct-style-quote-island',kernelSha256:hash(readFileSync(root+'/bend2/bend.ts')),sourceSha256:hash(readFileSync(join(dir,'quote.bend'))),driverSha256:hash(readFileSync(fileURLToPath(import.meta.url))),compilerSha256:hash(readFileSync(root+'/bend2/comp.ts')),baseSha256:hash(readFileSync(root+'/bend2/base.bend')),limits:{memoryMiB:2048,rssMiB:2048,timeoutMs:300000},patches:0,unsafe:false,semanticRows:[]};
let K:any;let phase='kernel-pin';
try {
 if(report.kernelSha256!==pin)throw Error('kernel pin mismatch');
 K=await import(root+'/bend2/bend.ts');
 // Dynamic loading preserves the experiment's pre-execution kernel hash boundary.
 const C=await import(root+'/bend2/comp.ts');
 phase='load';const book=K.book_nil();const seen=new Map();
 await K.book_load(book,join(dir,'quote.bend'),'',seen);
 report.modules=[...seen].map(([path,namespace])=>({path,namespace,sha256:hash(readFileSync(path))}));
 phase='book_valid';const t=performance.now();K.book_valid(book);
 report.holes=book.hols;
 report.checkedBodies=Object.entries(book.tlds).filter(([,d]:any)=>d.$==='Def'&&d.v!==null).map(([name,d]:any)=>({name,checked:d.e!==undefined}));
 if(book.hols||report.checkedBodies.some((d:any)=>!d.checked))throw Error('Unchecked body or hole');
 report.checkMs=performance.now()-t;
 phase='emit';const image=C.js_lib(book,true,{exports:['js_quote','js_quote_chars','js_escape_char']});
 writeFileSync(join(dir,'quote.mjs'),image,{flag:'wx'});report.emittedSha256=hash(image);report.emittedBytes=Buffer.byteLength(image);
 phase='semantic-smoke';const api=(await import(join(dir,'quote.mjs'))).default;
 const short:[string,string,string][]=[
  ['empty','','""'],['ascii','hello','"hello"'],
  ['six-escapes','"\\\n\r\t\0','"\\"\\\\\\n\\r\\t\\u0000"'],
  ['unchanged-controls','\x01\b\v\f\x1f\x7f','"\x01\b\v\f\x1f\x7f"'],
  ['bmp','é漢\u2028\u2029','"é漢\u2028\u2029"'],
  ['non-bmp','😀𝄞\u{10ffff}','"😀𝄞\u{10ffff}"'],
  ['mixed','a😀\n"\\\0z','"a😀\\n\\"\\\\\\u0000z"']
 ];
 const summarize=(s:string)=>s.length<=256?{text:s}:{utf16Length:s.length,codepoints:[...s].length,sha256:hash(s)};
 function smoke(name:string,input:string,expected:string){
  const row:any={name,input:summarize(input),expected:summarize(expected)};const t=performance.now();
  try{const observed=api.js_quote(input);row.observed=summarize(observed);row.equal=observed===expected;}
  catch(error){row.equal=false;row.error=String(error);row.stack=error instanceof Error?error.stack:undefined;}
  row.elapsedMs=performance.now()-t;report.semanticRows.push(row);
 }
 for(const row of short)smoke(...row);
 for(const n of [1000,10000,100000]){
  smoke('long-ascii-'+n,'a'.repeat(n),'"'+'a'.repeat(n)+'"');
  smoke('long-escape-nonbmp-'+n,'😀\n'.repeat(n),'"'+'😀\\n'.repeat(n)+'"');
 }
 report.status=report.semanticRows.every((r:any)=>r.equal)?'PASS':'SEMANTIC_OR_STACK_LIMIT';
}catch(error){report.status='FAIL';report.failure={phase,diagnostic:K&&error&&typeof error==='object'&&'$'in error&&error.$==='Err'?K.err_show(error):String(error)};}
report.retainedBytes=readdirSync(dir).reduce((s,n)=>s+statSync(join(dir,n)).size,0);
writeFileSync(join(dir,'receipt.json'),JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({status:report.status,phase,sourceSha256:report.sourceSha256,checkedBodies:report.checkedBodies?.length,holes:report.holes,checkMs:report.checkMs,emittedSha256:report.emittedSha256,rows:report.semanticRows.map((r:any)=>({name:r.name,equal:r.equal,error:r.error,elapsedMs:r.elapsedMs})),failure:report.failure,receipt:join(dir,'receipt.json')}));
if(report.status!=='PASS')process.exitCode=1;
